{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'norm' p, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) med_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-route-service' AND (span_name LIKE 'SELECT%' OR span_name IN ('Transaction.commit','RouteRepository.findAll','RouteRepository.findById')) GROUP BY ALL UNION ALL SELECT 'ab', span_name, count(*), round(approx_quantile(duration,0.5)/1e6,1), round(approx_quantile(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-route-service' AND (span_name LIKE 'SELECT%' OR span_name IN ('Transaction.commit','RouteRepository.findAll','RouteRepository.findById')) GROUP BY ALL ORDER BY 2,1",
          "claim": "Route-service DB spans (SELECT ts.route, RouteRepository.findAll/findById, Transaction.commit) rose from sub-ms medians to hundreds of ms or seconds in the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT s.time, s.service_name, s.span_name, s.attr_span_kind, c.span_name cname, round(s.duration/1e6,1) s_ms, round(c.duration/1e6,1) c_ms FROM abnormal_traces s LEFT JOIN abnormal_traces c ON c.parent_span_id=s.span_id AND c.trace_id=s.trace_id WHERE s.trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-preserve-service') AND s.service_name='ts-route-service' ORDER BY s.time LIMIT 40",
          "claim": "In slow route-service traces, RouteRepository.findById and Transaction.commit take ~2s and ~0.4s, with DB child spans dominating the time."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, c.span_name cname, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) c_med, round(approx_quantile(p.duration,0.5)/1e6,1) p_med FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-service' AND c.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC LIMIT 20",
          "claim": "Route-service server spans (routes, routes/byIds, routes/{start}/{end}) are slow in every caller: ui-dashboard, basic, route-plan, admin-route, preserve."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, c.span_name cname, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) c_med, round(approx_quantile(p.duration,0.5)/1e6,1) p_med FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-service' AND c.attr_span_kind='Server' AND p.service_name='ts-ui-dashboard' GROUP BY ALL",
          "claim": "ui-dashboard's calls to route-service's routes endpoint take about 7.2s median in the incident, versus about 9ms before."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, c.span_name cname, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) c_med, round(approx_quantile(p.duration,0.5)/1e6,1) p_med FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-route-service' GROUP BY ALL",
          "claim": "Route-plan's calls to route-service take about 1.85s median, and route-plan's own spans grow to match."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, c.span_name cname, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) c_med, round(approx_quantile(p.duration,0.5)/1e6,1) p_med FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Travel-plan's calls to route-plan take about 0.5s median, and travel-plan's minStation spans take about 4.3s."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, c.span_name cname, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) c_med, round(approx_quantile(p.duration,0.5)/1e6,1) p_med FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-basic-service' AND c.service_name='ts-route-service' GROUP BY ALL",
          "claim": "Basic-service's calls to route-service byIds take about 215ms median, and basic's travels spans take about 219ms."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, c.span_name cname, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) c_med, round(approx_quantile(p.duration,0.5)/1e6,1) p_med FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-service' AND c.service_name='ts-basic-service' GROUP BY ALL",
          "claim": "Travel-service's calls to basic-service take about 340ms median in the incident, carrying the route-service delay upward."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-admin-route-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name psvc, c.service_name csvc, c.span_name cname, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) c_med, round(approx_quantile(p.duration,0.5)/1e6,1) p_med FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-admin-route-service' AND c.service_name='ts-route-service' GROUP BY ALL",
          "claim": "Admin-route-service's calls to route-service take about 7.1s, and the admin route request reaches ui-dashboard at about 16.9s."
        }
      ]
    }
  ]
}

